-- PT120-S3-Q6. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT120-S3-Q6$batch10$ AND q.stimulus=$batch10$Citizen: The primary factor determining a dog’s disposition is not its breed, but its home environment. A bad owner can undo generations of careful breeding. Legislation focusing on specific breeds of dogs would not address the effects of human behavior in raising and training animals. As a result, such breed-specific legislation could never effectively protect the public from vicious dogs. Moreover, in my view, the current laws are perfectly adequate.$batch10$ AND q.prompt=$batch10$Which one of the following most accurately expresses the conclusion drawn by the citizen?$batch10$ AND q.correct_choice=$batch10$A$batch10$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT120-S3-Q6$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT120-S3-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Evidence$batch10$, $batch10$Home environment, not breed, mainly determines a dog's disposition. A bad owner can undo generations of breeding.$batch10$), (1, $batch10$Intermediate Conclusion$batch10$, $batch10$Breed-specific legislation wouldn't address how people raise and train dogs.$batch10$), (2, $batch10$Conclusion$batch10$, $batch10$So breed-specific legislation could never effectively protect the public from vicious dogs.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"As a result" marks the conclusion. The last sentence, that current laws are adequate, is an extra opinion added with "moreover." It doesn't support the claim and isn't supported by it.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Breed-specific legislation can't effectively protect the public from vicious dogs.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT120-S3-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the sentence "As a result" introduces. Nothing else in the argument is supported by it.$batch10$), ($batch10$B$batch10$, $batch10$This is close to the citizen's first claim, which supports everything after it. It's a premise, not the conclusion.$batch10$), ($batch10$C$batch10$, $batch10$This supports the main conclusion. The legislation fails because it can't address home environment.$batch10$), ($batch10$D$batch10$, $batch10$This restates the second sentence, which supports the claim that environment matters most.$batch10$), ($batch10$E$batch10$, $batch10$The citizen says breed-specific legislation fails to address human behavior. The current laws are said to be adequate, not to fail at this.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT120-S3-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
